-- =====================================================================
-- UBIPHARM CRM - Modeles de messages de depart
-- Marketing : modeles de base d'UbiSenderPro encore absents (promotions UG,
-- disponibilites et ruptures, rappel de garde, anniversaire), adaptes aux
-- variables du CRM. Recouvrement : les deux courriers de relance d'UBIPHARM
-- (preventive et echue). Tous restent modifiables, archivables et
-- exportables en Word ; un modele deja cree sous le meme nom est garde.
-- =====================================================================

INSERT INTO crm_modele_message (module, nom, type_campagne, type_information, canal, contenu, cree_par, created_at)
SELECT m.module, m.nom, m.type_campagne, m.type_information, 'WHATSAPP', m.contenu, u.id, UTC_TIMESTAMP() FROM (
    SELECT 'MARKETING' module, 'Promo · Annonce mensuelle' nom, 'PROMOTION' type_campagne, NULL type_information,
           '📢🔥 *PROMOTIONS UG DU MOIS* 🔥📢\n\nCher client *{nom_pharmacie}*,\n\n🎉 Découvrez nos offres promotionnelles *{promotion_nom}*, valables du *{promotion_debut}* au *{promotion_fin}*.\n\n💥 Bénéficiez d''unités gratuites sur une sélection de produits :\n\n{produits_promotion}\n\n📦 Les offres sont disponibles dans la limite des quantités prévues.\n\n📎 Consultez le fichier Excel joint pour préparer facilement votre commande sur *EXTRANET*.\n\n💻 Profitez de ces offres dès maintenant !\n\n*Direction Commerciale*' contenu
    UNION ALL SELECT 'MARKETING', 'Promo · Lancement', 'PROMOTION', NULL,
           '🚀🎁 *NOUVELLE PROMOTION UG* 🎁🚀\n\nCher client *{nom_pharmacie}*,\n\nLa promotion *{promotion_nom}* commence aujourd''hui !\n\n📅 Offre valable du *{promotion_debut}* au *{promotion_fin}*.\n\n💥 Produits concernés et avantages :\n\n{produits_promotion}\n\n💻 Passez votre commande via *EXTRANET* pendant la période de validité de l''offre.\n\n*Direction Commerciale*'
    UNION ALL SELECT 'MARKETING', 'Promo · Derniers jours', 'PROMOTION', NULL,
           '✨⏳ *PROMOTION UG · DERNIERS JOURS* ⏳✨\n\nCher client *{nom_pharmacie}*,\n\nL''offre d''unités gratuites *{promotion_nom}* arrive bientôt à expiration.\n\n📅 Date de fin : *{promotion_fin}*.\n\n🎁 Profitez-en encore sur les produits suivants :\n\n{produits_promotion}\n\n💻 Préparez votre commande et transmettez-la dès maintenant via *EXTRANET*.\n\nNe laissez pas passer ces dernières opportunités !\n\n*Direction Commerciale*'
    UNION ALL SELECT 'MARKETING', 'Promo · Dernière chance', 'PROMOTION', NULL,
           '⏰🔥 *DERNIÈRE CHANCE · PROMOTION UG* 🔥⏰\n\nCher client *{nom_pharmacie}*,\n\nLa promotion *{promotion_nom}* prend fin le *{promotion_fin}*.\n\nC''est votre dernière occasion de bénéficier des unités gratuites sur les produits concernés :\n\n{produits_promotion}\n\n💻 Finalisez votre commande sur *EXTRANET*.\n\nAprès cette date, les conditions promotionnelles ne seront plus applicables.\n\n*Direction Commerciale*'
    UNION ALL SELECT 'MARKETING', 'Dispo · Produits disponibles', 'PROMOTION', NULL,
           '📢🚨 *UBI INFO · PRODUITS DISPONIBLES* 🚨📢\n\n🌟 Bonne nouvelle ! 🌟\n\nCher client *{nom_pharmacie}*,\n\nNous avons le plaisir de vous informer de la disponibilité des produits suivants :\n\n{produits_disponibles}\n\n📍 Ces produits sont disponibles dès maintenant auprès d''UBIPHARM, agence de *{agence}*.\n\n💻 Passez votre commande sur *EXTRANET* afin de sécuriser votre stock.\n\nLes produits sont disponibles dans la limite des quantités en stock.\n\nÀ très bientôt !\n\n*Direction Commerciale UBIPHARM*'
    UNION ALL SELECT 'MARKETING', 'Dispo · Retour de rupture', 'PROMOTION', NULL,
           '📢🚨 *UBI INFO · RETOUR DE RUPTURE* 🚨📢\n\n🌟 Bonne nouvelle ! 🌟\n\nCher client *{nom_pharmacie}*,\n\nNous avons le plaisir de vous informer du retour en stock des produits suivants :\n\n{produits_disponibles}\n\n⚠️ Attention : les quantités disponibles sont limitées.\n\nPour réserver vos quantités :\n👉 {lien_commande}\n\nNous vous remercions pour votre confiance et votre fidélité.\n\n🌟 Avec UBIPHARM, vous êtes entre de bonnes mains.\n\n*Direction Commerciale UBIPHARM*'
    UNION ALL SELECT 'MARKETING', 'Dispo · Stock limité', 'PROMOTION', NULL,
           '📢🚨 *UBI INFO · STOCK LIMITÉ* 🚨📢\n\nCher client *{nom_pharmacie}*,\n\nLes produits suivants sont disponibles en quantités limitées :\n\n{produits_disponibles}\n\n📍 Disponibles auprès d''UBIPHARM, agence de *{agence}*, dans la limite des stocks.\n\n👉 Pour réserver vos quantités : {lien_commande}\n\n💻 Nous vous invitons à passer commande rapidement sur *EXTRANET*.\n\n*Direction Commerciale UBIPHARM*'
    UNION ALL SELECT 'MARKETING', 'Dispo · Risque de rupture', 'PROMOTION', NULL,
           '📢🚨 *UBI ALERTE · RISQUE DE RUPTURE* 🚨📢\n\nCher client *{nom_pharmacie}*,\n\nNous vous invitons à consulter le bulletin joint sur les produits présentant un risque de rupture.\n\n📄 Il contient la liste des produits concernés et les informations utiles pour anticiper vos besoins.\n\nNous vous recommandons d''évaluer votre stock et de préparer vos commandes dans les meilleurs délais.\n\n✨ Merci pour votre confiance et votre fidélité.\n\n🌟 Avec UBIPHARM, vous êtes entre de bonnes mains.\n\n*Direction Commerciale UBIPHARM*'
    UNION ALL SELECT 'MARKETING', 'Dispo · Rupture confirmée', 'PROMOTION', NULL,
           '📢🚨 *UBI INFO · RUPTURE DE STOCK* 🚨📢\n\nCher client *{nom_pharmacie}*,\n\nNous vous informons que les produits listés dans le document joint sont actuellement en rupture de stock.\n\nNous mettons tout en œuvre pour un réapprovisionnement dans les meilleurs délais et reviendrons vers vous dès leur disponibilité.\n\nMerci de votre compréhension et de votre fidélité.\n\n*Direction Commerciale UBIPHARM*'
    UNION ALL SELECT 'MARKETING', 'Info · Rappel de garde', 'INFORMATION', 'INFORMATION_GARDE',
           '📢🚨 *RAPPEL · GARDE À VENIR* 🚨📢\n\nCher client *{nom_pharmacie}*,\n\nRappel : à l''occasion de *{jour_ferie}*, pensez à transmettre vos commandes à l''agence de *{agence}* avant *{heure_limite_commande}*.\n\n💻 Privilégiez *EXTRANET* pour la saisie.\n\nPharmacien de garde : *{pharmacien_garde}*\n📞 *{telephone_pharmacien}*\n\n*{direction_signataire}*'
    UNION ALL SELECT 'MARKETING', 'Anniversaire client', 'PROMOTION', NULL,
           '🎉 *Joyeux anniversaire !* 🎉\n\n*{nom_client}*,\n\nEn ce jour spécial, toute l''équipe UBIPHARM tient à vous souhaiter un très bel anniversaire ! 🎂\n\nQue cette journée vous apporte bonheur, santé et réussite, aussi bien sur le plan personnel que professionnel.\n\nMerci pour votre confiance et pour ce précieux partenariat. 🙏\n\nProfitez pleinement de votre journée ! 🥂\n\nAu plaisir de vous accompagner encore longtemps.\n\n*L''équipe UBIPHARM*'
    -- Courriers de relance fournis par UBIPHARM ; le delai avant echeance suit les delais de relance
    UNION ALL SELECT 'RECOUVREMENT', 'Relance préventive', 'AVANT_ECHEANCE', NULL,
           'Bonjour Docteur *{nom_client}*,\n\nSauf erreur ou omission de notre part, nous vous informons que la facture ou l''étalement ci-dessous arrivera à échéance dans {jours_avant_echeance} jour(s) :\n\n* Nom de l''officine : *{nom_pharmacie}*\n* Compte : *{numero_compte}*\n* SType : *{sous_type}*\n* Numéro : *{reference_facture}*\n* Date d''échéance : *{date_echeance}*\n* Date comptable : *{date_facture}*\n* Montant : *{montant}* FCFA\n\nSi votre règlement a déjà été effectué, nous vous remercions de ne pas tenir compte de ce message.\nNous restons à votre entière disposition pour toute information complémentaire.\n\nUbipharm-Côte d''Ivoire'
    UNION ALL SELECT 'RECOUVREMENT', 'Relance échue', 'APRES_ECHEANCE', NULL,
           'Bonjour Docteur *{nom_client}*,\n\nSauf erreur ou omission de notre part, il apparaît que la facture ou l''étalement ci-dessous est arrivé(e) à échéance :\n\n* Nom de l''officine : *{nom_pharmacie}*\n* Compte : *{numero_compte}*\n* SType : *{sous_type}*\n* Numéro : *{reference_facture}*\n* Date d''échéance : *{date_echeance}*\n* Montant : *{montant}* FCFA\n* Date d''édition : *{date_facture}*\n\nEn l''absence de régularisation, cette situation pourrait entraîner une interruption du traitement de vos commandes.\nNous vous présentons nos excuses pour les désagréments que cela pourrait occasionner.\n\nSi votre règlement a été effectué entre-temps, nous vous remercions de ne pas tenir compte de ce message.\n\nPour toute information complémentaire, notre équipe reste à votre entière disposition.\n\nUbipharm-Côte d''Ivoire'
) m JOIN crm_utilisateur u ON u.login = 'admin'
WHERE NOT EXISTS (SELECT 1 FROM crm_modele_message e WHERE e.nom = m.nom);
